def rot13_lowercase_only(text: str) -> str:
    result = ''
    for ch in text:
        if 'a' <= ch <= 'z':
            result += chr((ord(ch) - 97 + 13) % 26 + 97)
        else:
            result += ch
    return result

def solution(text: str) -> str:
    res = []
    for ch in text:
        if 'a' <= ch <= 'z':
            res.append(chr((ord(ch) - ord('a') + 13) % 26 + ord('a')))
        elif 'A' <= ch <= 'Z':
            res.append(chr((ord(ch) - ord('A') + 13) % 26 + ord('A')))
        else:
            res.append(ch)
    return ''.join(res)
